class Inventory:
    def __init__(self):
        # internal storage mapping items to quantities
        self._stock = {}

    def add(self, item, qty):
        """Add qty of item to inventory. qty must be a positive integer."""
        if not isinstance(qty, int) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")
        self._stock[item] = self._stock.get(item, 0) + qty

    def remove(self, item, qty):
        """Remove qty of item from inventory. Raises ValueError if insufficient stock
        or qty is not a positive integer."""
        if not isinstance(qty, int) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")
        current = self._stock.get(item, 0)
        if qty > current:
            raise ValueError("Not enough stock to remove")
        # perform removal
        new_qty = current - qty
        if new_qty:
            self._stock[item] = new_qty
        else:
            # remove item entry if quantity drops to zero
            self._stock.pop(item, None)

    def stock(self, item):
        """Return current stock quantity for item, 0 if unknown."""
        return self._stock.get(item, 0)
